enum class Muscle(val label: String) {
    SIDE_DELT("Yan omuz"), REAR_DELT("Arka omuz"), FRONT_DELT("Ön omuz"), UPPER_CHEST("Üst göğüs"),
    CHEST("Göğüs"), LATS("Kanat (latissimus)"), UPPER_BACK("Üst sırt / trapez orta"), CORE("Core"),
    QUADS("Ön bacak"), HAMSTRINGS("Arka bacak"), GLUTES("Kalça"), CALVES("Baldır"),
    BICEPS("Biceps"), TRICEPS("Triceps"), MOBILITY("Mobilite")
}

enum class ExKind { COMPOUND, ISOLATION, CORE, MOBILITY }

data class Exercise(
    val id: String,
    val name: String,
    val muscles: List<Muscle>,
    /** Hareket için gereken ekipmanların tamamı. Boşsa yalnızca vücut ağırlığı. */
    val requires: Set<Equip>,
    val kind: ExKind,
    val steps: List<String>,
    val cues: List<String>,
    val mistakes: List<String>,
    val timed: Boolean = false,
)

