    private val byId = all.associateBy { it.id }
    fun get(id: String): Exercise? = byId[id]

    fun available(ex: Exercise, equipment: Set<Equip>): Boolean =
        ex.requires.all { it == BODYWEIGHT || it in equipment }
}
